def f(n):
    """
    Returns a list of size n where the value at index i is the factorial of i if i is even,
    or the sum of numbers from 1 to i if i is odd.
    """
    def factorial(x):
        """Calculates the factorial of a given number x."""
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x - 1)

    def sum_of_numbers(x):
        """Calculates the sum of numbers from 1 to x."""
        return sum(range(1, x + 1))

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_of_numbers(i))
    return result

def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    words = test.split()
    letter_count = {}

    for word in words:
        if word in letter_count:
            letter_count[word] += 1
        else:
            letter_count[word] = 1

    max_count = max(letter_count.values())
    result = {letter: count for letter, count in letter_count.items() if count == max_count}

    return result

def valid_date(date):
    """
    Validates a given date string and returns True if the date is valid otherwise False.
    The date is valid if all of the following rules are satisfied:
    1. The date string is not empty.
    2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. 
       And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. 
       And, the number of days is not less than 1 or higher than 29 for the month 2.
    3. The months should not be less than 1 or higher than 12.
    4. The date should be in the format: mm-dd-yyyy
    """
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    month, day, year = parts

    if not (month.isdigit() and day.isdigit() and year.isdigit()):
        return False

    month, day, year = int(month), int(day), int(year)

    if month < 1 or month > 12:
        return False

    if month in {1, 3, 5, 7, 8, 10, 12}:
        if day < 1 or day > 31:
            return False
    elif month in {4, 6, 9, 11}:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if day < 1 or day > 29:
                return False
        else:
            if day < 1 or day > 28:
                return False

    return True

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        return sum(1 for char in txt if 'a' <= char <= 'z' and (ord(char) - ord('a')) % 2 == 1)

def tri(n):
    """
    Calculate the first n + 1 numbers of the Tribonacci sequence.

    Parameters:
    n (int): A non-negative integer representing the number of terms in the sequence.

    Returns:
    list: A list containing the first n + 1 numbers of the Tribonacci sequence.
    """
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]

    sequence = [1, 3]

    for i in range(2, n + 1):
        if i % 2 == 0:
            sequence.append(1 + i / 2)
        else:
            sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i + 1])

    return sequence

def is_nested(string):
    '''
    Determines if there is a valid subsequence of brackets in the string where at least one bracket is nested.

    :param string: A string containing only square brackets.
    :return: True if there is a nested bracket subsequence, False otherwise.
    '''
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if not stack:
                return False
            stack.pop()
            if stack:
                return True
    return False

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def convert_to_float(value):
        if isinstance(value, str):
            value = value.replace(',', '.')
        return float(value)

    a_float = convert_to_float(a)
    b_float = convert_to_float(b)

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = []
    i = 0
    while i < len(text):
        if text[i] == ' ':
            consecutive_spaces = 0
            while i < len(text) and text[i] == ' ':
                consecutive_spaces += 1
                i += 1
            if consecutive_spaces > 2:
                result.append('-')
            else:
                result.append('_' * consecutive_spaces)
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def sum_squares(lst):
    """
    This function will take a list of integers. For all entries in the list, the function shall square the integer entry if its index is a 
    multiple of 3 and will cube the integer entry if its index is a multiple of 4 and not a multiple of 3. The function will not 
    change the entries in the list whose indexes are not a multiple of 3 or 4. The function shall then return the sum of all entries. 

    Examples:
    For lst = [1,2,3] the output should be 6
    For lst = []  the output should be 0
    For lst = [-1,-5,2,-1,-5]  the output should be -126
    """
    for i in range(len(lst)):
        if i % 4 == 0:
            lst[i] **= 3
        elif i % 3 == 0:
            lst[i] **= 2
    return sum(lst)

