def order_by_points(nums):
    """
    Sorts the given list of integers in ascending order according to the sum of their digits.
    If there are several items with similar sum of their digits, they are ordered based on their index in the original list.

    :param nums: List of integers to be sorted.
    :return: A new list of integers sorted according to the specified criteria.
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def specialFilter(nums):
    """
    Returns the count of numbers in the list that are greater than 10 and have both
    the first and last digits as odd numbers (1, 3, 5, 7, 9).

    :param nums: List of integers
    :return: Integer count of special numbers
    """
    def is_odd_digit(digit):
        return digit in {'1', '3', '5', '7', '9'}

    def has_odd_first_and_last_digits(num):
        num_str = str(abs(num))
        return is_odd_digit(num_str[0]) and is_odd_digit(num_str[-1])

    return sum(1 for num in nums if num > 10 and has_odd_first_and_last_digits(num))

def get_max_triples(n):
    """
    Generates an array a of length n where a[i] = i * i - i + 1 for each i.
    Returns the number of triples (a[i], a[j], a[k]) where i < j < k and a[i] + a[j] + a[k] is a multiple of 3.

    :param n: Length of the array
    :return: Number of valid triples
    """
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1

    return count

